{"implementation":"import math


def _require_mapping(value, name):
    if not isinstance(value, dict):
        raise ValueError(f"{name} must be an object")


def _require_number(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError(f"{name} must be a finite number")
    return float(value)


def solve(case):
    _require_mapping(case, "case")

    if "threshold" not in case:
        raise ValueError("missing threshold")
    if "calls" not in case:
        raise ValueError("missing calls")

    threshold = _require_number(case["threshold"], "threshold")
    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    diagnostics = []
    accepted_call_ids = []

    for index, call in enumerate(calls):
        _require_mapping(call, f"calls[{index}]")
        for field in ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable"):
            if field not in call:
                raise ValueError(f"missing {field}")

        call_id = call["call_id"]
        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")

        loss_without = _require_number(call["loss_without_call"], "loss_without_call")
        loss_with = _require_number(call["loss_with_call"], "loss_with_call")
        prediction_tokens = _require_number(call["prediction_tokens"], "prediction_tokens")
        if prediction_tokens < 0:
            raise ValueError("prediction_tokens must be non-negative")

        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be a boolean")

        normalized_gain = (loss_without - loss_with) / max(1.0, prediction_tokens)
        accepted = bool(parseable and normalized_gain >= threshold)

        if accepted:
            accepted_call_ids.append(call_id)

        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": round(normalized_gain, 6),
        })

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
"}
